    'English and Korean are now supported! However, translations were done by AI and may contain errors. We appreciate your feedback on Discord.': '现已支持英语和韩语！译文由 AI 生成，可能存在错误，欢迎通过 Discord 反馈。',
    'EN/KO supported! AI-translated — feedback welcome on Discord.': '支持英语和韩语！AI 翻译，欢迎在 Discord 反馈。',
    'This site is an unofficial fan site and is not affiliated with SQUARE ENIX CO., LTD.': '本站为非官方玩家网站，与史克威尔艾尼克斯公司无隶属关系。',
    'Miramiru is a fan-made site not affiliated with SQUARE ENIX.': 'Miramiru 为玩家制作的网站，与史克威尔艾尼克斯无隶属关系。',
    'We primarily showcase devices and products the team actually uses.': '主要展示团队实际使用的设备和产品。',
    'Posts a link to X. You\'ll need to attach the image manually.': '将链接分享到 X，图片需要手动附加。',
