    'Miramiru への単発支援に感謝して贈られる、温かいピンクのハートバッジ。': '温暖的粉色爱心徽章，用于感谢向 Miramiru 提供一次性赞助的用户。',
    'Miramiru에 대한 단발 후원에 감사하는 따뜻한 핑크 하트 배지.': '温暖的粉色爱心徽章，用于感谢向 Miramiru 提供一次性赞助的用户。',
    'Make a one-time Ko-fi tip of ¥300 or more. Granted permanently (never expires).': '在 Ko-fi 一次性赞助至少 ¥300 后永久获得，不会到期。',
