    'Simply upload a screenshot of the in-game Coordinate View and our image recognition automatically identifies gear icons across all 12 slots. No more tedious manual entry.': '上传游戏内搭配预览界面的截图，即可通过图像识别自动检测全部 12 个部位的装备图标，无需逐项手动输入。',
    'ゲーム内のコーディネートビュー画面のスクリーンショットをアップロードするだけで、装備アイコンを画像認識し、12スロットすべての装備名を自動で入力。面倒な手入力から解放されます。': '上传游戏内搭配预览界面的截图，即可通过图像识别自动检测全部 12 个部位的装备图标，无需逐项手动输入。',
    '게임 내 투영 장비보기 화면의 스크린샷을 업로드하기만 하면, 이미지 인식으로 장비 아이콘을 식별하여 12슬롯 모든 장비명을 자동으로 입력합니다. 번거로운 수동 입력에서 해방됩니다.': '上传游戏内搭配预览界面的截图，即可通过图像识别自动检测全部 12 个部位的装备图标，无需逐项手动输入。',
