    '各装備の入手方法をカラーバッジで表示。課金アイテムなのか、クラフトで作れるのか、ダンジョンでドロップするのか——ミラプリの再現コストが一目瞭然です。': '每件装备均有不同颜色的获取途径标记。商城、制作、副本掉落等来源，让你一眼了解复刻整套幻化的成本。',
    '각 장비의 입수 방법을 컬러 뱃지로 표시합니다. 과금 아이템인지, 제작 가능한지, 던전 드롭인지 -- 투영 재현 비용을 한눈에 파악할 수 있습니다.': '每件装备均有不同颜色的获取途径标记。商城、制作、副本掉落等来源，让你一眼了解复刻整套幻化的成本。',
