    'Yes, the creator is an active FFXIV player (Niique Noela / Anima (Mana)).\nSome people suspected impersonation since I previously said I\'d quit FF on X, but I just couldn\'t stop playing.\nAs a solo developer, there are still many rough edges, but I\'d love to hear your feedback on Discord or X.': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。\n由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。\n个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    'Yes, the creator is an active FFXIV player (Niique Noela / Anima (Mana)). Some people suspected impersonation since I previously said I\'d quit FF on X, but I just couldn\'t stop playing. As a solo developer, there are still many rough edges, but I\'d love to hear your feedback on Discord or X.': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。 由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。 个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    'Yes, the creator is an active FFXIV player (Niique Noela / Anima (Mana)).': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。',
    'Some people suspected impersonation since I previously said I\'d quit FF on X, but I just couldn\'t stop playing.': '由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。',
    'As a solo developer, there are still many rough edges, but I\'d love to hear your feedback on Discord or X.': '个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    'はい、作者は現役のFFXIVプレイヤー（Niique Noela / Anima(Mana)）です。\nXで以前FFをやめると言ったのにこんなサイトを作ったのでなりすましを疑われたりもしましたが、やめられなかっただけです。\n個人開発のため至らない点も多いですが、DiscordやXでお気軽にフィードバックをいただけると嬉しいです。': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。\n由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。\n个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    'はい、作者は現役のFFXIVプレイヤー（Niique Noela / Anima(Mana)）です。 Xで以前FFをやめると言ったのにこんなサイトを作ったのでなりすましを疑われたりもしましたが、やめられなかっただけです。 個人開発のため至らない点も多いですが、DiscordやXでお気軽にフィードバックをいただけると嬉しいです。': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。 由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。 个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    'はい、作者は現役のFFXIVプレイヤー（Niique Noela / Anima(Mana)）です。': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。',
    'Xで以前FFをやめると言ったのにこんなサイトを作ったのでなりすましを疑われたりもしましたが、やめられなかっただけです。': '由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。',
    '個人開発のため至らない点も多いですが、DiscordやXでお気軽にフィードバックをいただけると嬉しいです。': '个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    '네, 제작자는 현역 FFXIV 플레이어(Niique Noela / Anima(Mana))입니다.\nX에서 이전에 FF를 그만둔다고 했는데 이런 사이트를 만들어서 사칭 의심을 받기도 했지만, 단지 그만둘 수 없었을 뿐입니다.\n개인 개발이라 부족한 점도 많지만, Discord나 X에서 편하게 피드백을 주시면 감사하겠습니다.': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。\n由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。\n个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    '네, 제작자는 현역 FFXIV 플레이어(Niique Noela / Anima(Mana))입니다. X에서 이전에 FF를 그만둔다고 했는데 이런 사이트를 만들어서 사칭 의심을 받기도 했지만, 단지 그만둘 수 없었을 뿐입니다. 개인 개발이라 부족한 점도 많지만, Discord나 X에서 편하게 피드백을 주시면 감사하겠습니다.': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。 由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。 个人开发仍有不少不完善之处，欢迎通过 Discord 或 X 提供反馈。',
    '네, 제작자는 현역 FFXIV 플레이어(Niique Noela / Anima(Mana))입니다.': '是的，开发者目前仍在玩 FF14（Niique Noela / Anima（Mana））。',
    'X에서 이전에 FF를 그만둔다고 했는데 이런 사이트를 만들어서 사칭 의심을 받기도 했지만, 단지 그만둘 수 없었을 뿐입니다.': '由于我此前在 X 上说过已经离开 FF14，有些人怀疑账号被冒用，但其实只是忍不住又回来了。',
