    'Ko-fi is a UK-based creator support platform. No account is required to tip — you can donate or subscribe in a few clicks with credit card, Apple Pay, or Google Pay. Payments are processed by Stripe, so your card details never reach Miramiru.': 'Ko-fi 是英国的创作者支持平台，无需注册账号，即可使用信用卡、Apple Pay 或 Google Pay 完成捐助或订阅。付款由 Stripe 处理，银行卡信息不会传递给 Miramiru。',
    'Ko-fi は英国発のクリエイター支援プラットフォームです。アカウント登録は不要で、クレジットカード・Apple Pay・Google Pay から数クリックで寄付・月額サポートができます。決済は Stripe が処理するため、カード情報が Miramiru に渡ることはありません。': 'Ko-fi 是英国的创作者支持平台，无需注册账号，即可使用信用卡、Apple Pay 或 Google Pay 完成捐助或订阅。付款由 Stripe 处理，银行卡信息不会传递给 Miramiru。',
    'Ko-fi는 영국 기반의 크리에이터 후원 플랫폼입니다. 계정 등록 없이 신용카드·Apple Pay·Google Pay로 몇 번의 클릭만으로 기부 또는 월정액 후원이 가능합니다. 결제는 Stripe가 처리하므로 카드 정보가 Miramiru에 전달되지 않습니다.': 'Ko-fi 是英国的创作者支持平台，无需注册账号，即可使用信用卡、Apple Pay 或 Google Pay 完成捐助或订阅。付款由 Stripe 处理，银行卡信息不会传递给 Miramiru。',
